create function touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table clients (id uuid primary key default gen_random_uuid(), name text not null unique, address text not null, jurisdiction text not null check(jurisdiction in ('NZ','AU')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger clients_updated before update on clients for each row execute function touch_updated();
create table vineyards (id uuid primary key default gen_random_uuid(), name text not null unique, grower text not null, region text, address text, source_id text unique, source_record jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger vineyards_updated before update on vineyards for each row execute function touch_updated();
create table vessels (id uuid primary key default gen_random_uuid(), name text not null unique, capacity_l numeric(14,3) not null check(capacity_l>0), location text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger vessels_updated before update on vessels for each row execute function touch_updated();
create table lots (id uuid primary key default gen_random_uuid(), name text not null unique, client_id uuid not null references clients, status text not null default 'available' check(status in ('available','hold')), received_on date not null, source_ref text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger lots_updated before update on lots for each row execute function touch_updated();
create table origins (id uuid primary key default gen_random_uuid(), lot_id uuid not null references lots, vineyard text not null, vintage integer not null check(vintage between 1900 and 2200), variety text not null, region text not null, fraction numeric(18,12) not null check(fraction>0 and fraction<=1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger origins_updated before update on origins for each row execute function touch_updated();
create table positions (id uuid primary key default gen_random_uuid(), lot_id uuid not null references lots, vessel_id uuid not null unique references vessels, litres numeric(14,3) not null check(litres>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger positions_updated before update on positions for each row execute function touch_updated();
create table lineage (id uuid primary key default gen_random_uuid(), parent_id uuid not null references lots, child_id uuid not null references lots, litres numeric(14,3) not null check(litres>0), check(parent_id<>child_id), unique(parent_id,child_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger lineage_updated before update on lineage for each row execute function touch_updated();
create table operations (id uuid primary key default gen_random_uuid(), name text not null unique, lot_id uuid not null references lots, kind text not null check(kind in ('receive','transfer','blend','bottle','supply','loss','hold','release')), occurred_on date not null, recorded_by text not null, litres numeric(14,3) not null check(litres>=0), from_vessel text, to_vessel text, note text not null, evidence jsonb not null default '{}', retain_until date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger operations_updated before update on operations for each row execute function touch_updated();
create table analyses (id uuid primary key default gen_random_uuid(), lot_id uuid not null references lots, vessel text, sampled_on date not null, metric text not null, value numeric not null, unit text not null, lab_ref text not null, source_key text unique, source_record jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger analyses_updated before update on analyses for each row execute function touch_updated();
create table work_orders (id uuid primary key default gen_random_uuid(), name text not null unique, lot_id uuid not null references lots, kind text not null, due_on date not null, assigned_to text not null, status text not null default 'open' check(status in ('open','done','cancelled')), completed_on date, note text not null, check((status='done')=(completed_on is not null)), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger work_orders_updated before update on work_orders for each row execute function touch_updated();
create table additions (id uuid primary key default gen_random_uuid(), lot_id uuid not null references lots, occurred_on date not null, material text not null, supplier text not null, supplier_batch text not null, quantity numeric not null check(quantity>0), unit text not null, recorded_by text not null, note text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger additions_updated before update on additions for each row execute function touch_updated();
create table bottlings (id uuid primary key default gen_random_uuid(), name text not null unique, lot_id uuid not null references lots, bottled_on date not null, bottles integer not null check(bottles>0), bottle_ml integer not null check(bottle_ml>0), litres numeric(14,3) not null check(litres>0), packaging_ref text not null, recorded_by text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger bottlings_updated before update on bottlings for each row execute function touch_updated();
create table supplies (id uuid primary key default gen_random_uuid(), name text not null unique, lot_id uuid not null references lots, supplied_on date not null, recipient text not null, address text not null, litres numeric(14,3) not null check(litres>0), recorded_by text not null, statement_ref text not null, retain_until date not null, composition jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger supplies_updated before update on supplies for each row execute function touch_updated();
create table recalls (id uuid primary key default gen_random_uuid(), name text not null unique, performed_on date not null, lot_id uuid not null references lots, reviewer text not null, evidence text not null, follow_up text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger recalls_updated before update on recalls for each row execute function touch_updated();
create table notes (id uuid primary key default gen_random_uuid(), lot_id uuid not null references lots, note text not null, recorded_by text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger notes_updated before update on notes for each row execute function touch_updated();

create index operations_lot on operations(lot_id);
create index analyses_lot on analyses(lot_id,sampled_on);
create view cellar_view as select l.id,l.name as lot,c.name as owner,c.jurisdiction,v.name as vessel,v.location,p.litres,v.capacity_l,(v.capacity_l-p.litres) as spare_l,l.status,l.received_on,
(select max(a.sampled_on) from analyses a where a.lot_id=l.id) as last_sample
from positions p join lots l on l.id=p.lot_id join clients c on c.id=l.client_id join vessels v on v.id=p.vessel_id;
create view capacity_view as select v.name as vessel,v.location,v.capacity_l,coalesce(p.litres,0) as occupied_l,v.capacity_l-coalesce(p.litres,0) as spare_l,l.name as lot from vessels v left join positions p on p.vessel_id=v.id left join lots l on l.id=p.lot_id;
create view work_view as select w.id,w.name as job,l.name as lot,c.name as owner,w.kind,w.due_on,w.assigned_to,w.status,l.status as lot_status,w.note from work_orders w join lots l on l.id=w.lot_id join clients c on c.id=l.client_id;
create view attention_view as
select 'Overdue work' as issue,job as reference,owner,due_on::text as detail from work_view where status='open' and due_on<current_date
union all select 'Held wine',lot,owner,litres::text||' L in '||vessel from cellar_view where status='hold'
union all select 'Lab sample overdue',lot,owner,coalesce(last_sample::text,'No sample recorded') from cellar_view where last_sample is null or last_sample<current_date-14
union all select 'Missing origin',l.name,c.name,'Vineyard, vintage, variety and region need evidence' from lots l join clients c on c.id=l.client_id where not exists(select 1 from origins o where o.lot_id=l.id) or exists(select 1 from origins o where o.lot_id=l.id and (o.vineyard='' or o.variety='' or o.region=''))
union all select 'Missing supply statement',s.name,c.name,s.recipient from supplies s join lots l on l.id=s.lot_id join clients c on c.id=l.client_id where s.statement_ref='';
create view compliance_view as
select 'AU-LIP-3D' as rule,o.name as reference,'Operation recorded more than three days after event' as finding,'https://www.wineaustralia.com/news/articles/what-are-we-looking-for-during-an-audit' as source from operations o join lots l on l.id=o.lot_id join clients c on c.id=l.client_id where c.jurisdiction='AU' and o.created_at::date>o.occurred_on+3
union all select 'AU-LIP-7Y',o.name,'Retention does not cover seven years','https://www.wineaustralia.com/labelling/label-integrity-program' from operations o join lots l on l.id=o.lot_id join clients c on c.id=l.client_id where c.jurisdiction='AU' and o.retain_until<(o.occurred_on+interval '7 years')::date
union all select 'AU-LIP-SUPPLY',s.name,'Supply statement reference, recipient address or retention missing','https://www.wineaustralia.com/labelling/label-integrity-program' from supplies s join lots l on l.id=s.lot_id join clients c on c.id=l.client_id where c.jurisdiction='AU' and (s.statement_ref='' or s.address='' or s.retain_until<(s.supplied_on+interval '7 years')::date)
union all select 'TRACE-ORIGIN',reference,detail,'docs/compliance.md' from attention_view where issue='Missing origin'
union all select 'NZ-RECALL-12M',c.name,'No simulated or qualifying recall recorded in the last twelve months','https://www.mpi.govt.nz/food-business/food-recalls/doing-food-recall' from clients c where c.jurisdiction='NZ' and not exists(select 1 from recalls r join lots l on l.id=r.lot_id where l.client_id=c.id and r.performed_on>=(current_date-interval '12 months')::date)
union all select 'POLICY-HOLD',lot,'Winemaker release required before movement','docs/compliance.md' from cellar_view where status='hold'
union all select 'POLICY-LAB-14D',lot,'Sample absent or older than fourteen days','docs/compliance.md' from cellar_view where last_sample is null or last_sample<current_date-14;
create view owner_view as select c.name as owner,c.jurisdiction,coalesce((select sum(p.litres) from positions p join lots l on l.id=p.lot_id where l.client_id=c.id),0) as litres,
(select count(*) from work_orders w join lots l on l.id=w.lot_id where l.client_id=c.id and w.status='open' and w.due_on<current_date) as overdue_jobs,
(select count(*) from lots l where l.client_id=c.id and l.status='hold') as held_lots,
(select max(n.created_at)::date from notes n join lots l on l.id=n.lot_id where l.client_id=c.id) as last_note from clients c;
